// The site's reader for the DOCS PATH CONTRACT (docs/internal/docs-map.json, generated by
// tooling/gen-docs-map.mjs). The contract is the single source of truth for what is published
// and where it routes; every consumer here (nav, the [...slug] pages, the D4 link resolver,
// the search index) reads it instead of re-deriving paths from the mirror's layout.
//
// Read from the committed file via fs (not a bundler import) so it works the same in the Astro
// config, the markdown-pipeline plugin, and the plain-node pre-build script — none of which
// share an import root, and all of which run against the in-repo mirror.
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
// site/src/lib -> repo root -> docs/internal/docs-map.json
const MAP = JSON.parse(
  readFileSync(path.resolve(HERE, '../../../docs/internal/docs-map.json'), 'utf8')
);

export const productDocs = MAP.product ?? [];
export const engineeringDocs = MAP.engineering ?? [];

// docs/-relative source -> doc entry (either tier). The link/route authority.
const BY_SOURCE = new Map([...productDocs, ...engineeringDocs].map((d) => [d.source, d]));

// Resolve a docs/-relative source path (e.g. "internal/backend/architecture.md" or
// "public/getting-started.md") to its published doc entry, or null if unpublished. Exact
// case — the link resolver passes real on-disk paths.
export function docBySource(source) {
  return BY_SOURCE.get(source) ?? null;
}

// Map an Astro `engineering` content-collection entry to its contract doc. That collection's
// base is ../docs/internal, so an entry.id (no extension) corresponds to source
// `internal/<id>.md`. Astro LOWERCASES entry ids (so `README.md` loads as `…/readme`), which
// a case-sensitive lookup would drop — match case-insensitively. Returns null for a loaded
// file that is NOT in the published set.
const BY_SOURCE_LC = new Map(
  [...productDocs, ...engineeringDocs].map((d) => [d.source.toLowerCase(), d])
);
export function engDocForEntry(entry) {
  return BY_SOURCE_LC.get(`internal/${entry.id}.md`.toLowerCase()) ?? null;
}
